				if (input.IsOnButton(UIWindow.MoveRightButton, false))
				{
					moveValue.x += CursorMoveValue;
				}
				if (input.IsOnButton(UIWindow.MoveUpButton, false))
				{
					moveValue.y += CursorMoveValue;
				}
