		private void OnUpdate2DMode(float deltaTime) {
			int x = 0;
			int y = 0;
			if (input.IsRepeatButton(UIWindow.MoveLeftButton, false))
			{
				x--;
			}
			if (input.IsRepeatButton(UIWindow.MoveRightButton, false))
			{
				x++;
			}
			if (input.IsRepeatButton(UIWindow.MoveUpButton, false))
			{
				y++;
			}
			if (input.IsRepeatButton(UIWindow.MoveDownButton, false))
			{
				// shipped: down ASSIGNS -1 (csinv @01e714b8), so up + down gives -1 while left + right gives 0
				y = -1;
			}
			if (x != 0 || y != 0)
			{
				if (Capsule2DViewController.MoveGridCell(x, y))
				{
					selectedCapsule2DGridCell = Capsule2DViewController.GetCurrentGridCell();
					cursor.SetPosition(selectedCapsule2DGridCell.GetPosition());
					isHoverSetSealGridCell = selectedCapsule2DGridCell.IsSetSeal;
					UpdateKeyGuide(false);
					Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
				}
				else if (y == 1)
				{
					SealCategoryButton categoryButton = GetNearCategoryButton(Capsule2DViewController.GetCurrentGridCell().GetPosition());
					if (categoryButton != null)
					{
						cursor.SetPosition(categoryButton.GetPosition());
						CheckCursorRaycast(true, false, true);
						Capsule2DViewController.SetCurrentGridCell(null);
					}
					UpdateKeyGuide(false);
				}
			}
			if (input.IsPushButton(GameController.ButtonMask.StickRLeft, false) || input.IsPushButton(GameController.ButtonMask.StickRRight, false))
			{
				isAnimation = true;
				Capsule2DViewController.Reverse();
				Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
			}
		}
		private global::Dpr.UI.SealCategoryButton GetNearCategoryButton(global::UnityEngine.Vector3 pos) {
			SealCategoryButton nearButton = null;
			float minDistance = float.MaxValue;
			foreach (SealCategoryButton categoryButton in categoryButtons)
			{
				Vector3 diff = pos - categoryButton.GetPosition();
				float distance = diff.sqrMagnitude;
				if (distance < minDistance)
				{
					minDistance = distance;
					nearButton = categoryButton;
				}
			}
			return nearButton;
		}
		public void UpdateKeyGuide(bool isForce = false) {
			keyguideIdList.Clear();
			if (cursor.IsSelected)
			{
				if (isBindCategoryTab || isShowPullDown)
				{
					keyguideIdList.Add(KeyguideID.SEAL_CUSTOMIZE_DECIDE);
				}
				else if (!currentCapsuleInfo.Is3DEditMode || Capsule3DViewController.IsHitCapsule)
				{
					keyguideIdList.Add(KeyguideID.SEAL_CUSTOMIZE_PASTE);
				}
				if (pickedAffixSealId >= 0)
				{
					keyguideIdList.Add(KeyguideID.SEAL_CUSTOMIZE_SEAL_UNDO);
				}
			}
			else
			{
				if (!isBindCategoryTab)
				{
					if (isShowPullDown)
					{
						keyguideIdList.Add(KeyguideID.SEAL_CUSTOMIZE_DECIDE);
					}
					else
					{
						if (isHoverSetSealGridCell)
						{
							keyguideIdList.Add(KeyguideID.SEAL_CUSTOMIZE_GRAB);
						}
						keyguideIdList.Add(KeyguideID.SEAL_CUSTOMIZE_LISTRETURN);
						keyguideIdList.Add(KeyguideID.SEAL_CAPSULELIST_MODESWITCH);
					}
				}
				if (canSwitchPallet)
				{
					keyguideIdList.Add(KeyguideID.SEAL_CUSTOMIZE_PALETTESWITCH);
				}
			}
			if (canResetRotate)
			{
				keyguideIdList.Add(KeyguideID.SEAL_CUSTOMIZE_DIRECTION_UNDO);
			}
			keyguideIdList.Add(KeyguideID.SEAL_CUSTOMIZE_BACK);
			if (!isForce && keyguideParam.itemParams.Count == keyguideIdList.Count)
			{
				bool isSame = true;
				for (int i = 0; i < keyguideParam.itemParams.Count; i++)
				{
					if (keyguideParam.itemParams[i].keyguideId != keyguideIdList[i])
					{
						isSame = false;
						break;
					}
				}
				if (isSame)
				{
					return;
				}
			}
			keyguideParam.itemParams.Clear();
			for (int i = 0; i < keyguideIdList.Count; i++)
			{
				keyguideParam.itemParams.Add(new KeyguideItem.Param() { keyguideId = keyguideIdList[i] });
			}
			keyguide.Open(keyguideParam);
		}
