						int affixSealId = currentCapsuleInfo.AddAffixSeal((ushort)cursor.SelectedSealId, affixSealPosition);
						Capsule3DViewController.AffixSeal(affixSealId, cursor.SelectedSealId);
						CheckCategoryButtonEnable(categoryButtons[categoryIndexSelector.CurrentIndex]);
						RefreshCapsuleInfo(false);
						if (Dpr.BallDeco.BallDecoWork.GetSealCount(cursor.SelectedSealId) == 0)
						{
							cursor.Unselect();
							UpdateSwitchPalletIconActive();
						}
					}
					else
					{
						currentCapsuleInfo.SetAffixSeal(pickedSeal3DObject.AffixSealId, (ushort)cursor.SelectedSealId, affixSealPosition);
						Capsule3DViewController.AffixSealObject(pickedSeal3DObject);
						ClearPickedSeal();
						cursor.Unselect();
						UpdateSwitchPalletIconActive();
					}
					SmartPoint.AssetAssistant.Sequencer.Start(DelayCheckCursorRaycast(true, true, false));
					return DecideActionResult.AffixedSeal;
				}
				if (selectedCapsule2DGridCell == null)
				{
					return DecideActionResult.None;
				}
				if (selectedCapsule2DGridCell.IsSetSeal)
				{
					if (pickedCapsule2DGridCell == null)
					{
						currentCapsuleInfo.SwapAffixSeal(selectedCapsule2DGridCell.AffixSealId, (ushort)cursor.SelectedSealId);
					}
					else
					{
						currentCapsuleInfo.SwapEachAffixSeal(selectedCapsule2DGridCell.AffixSealId, pickedAffixSealId);
						currentCapsuleInfo.RemoveAffixSeal(pickedAffixSealId, true);
						pickedCapsule2DGridCell.ClearAffixSeal();
						ClearPickedSeal();
					}
					cursor.Unselect();
					RefreshCapsuleInfo(false);
					CheckCursorRaycast(true, true, false);
					UpdatePallet();
					return DecideActionResult.AffixedSeal;
				}
				if (pickedCapsule2DGridCell == null)
				{
					if (currentCapsuleInfo.IsAffixSealMaxCount)
					{
						OnSelectSealWhenAffixSealMaxCount?.Invoke();
						return DecideActionResult.Default;
					}
					int affixSealId = currentCapsuleInfo.AddAffixSeal((ushort)cursor.SelectedSealId, selectedCapsule2DGridCell.GetSealPosition());
					selectedCapsule2DGridCell.SetAffixSeal(affixSealId, cursor.SelectedSealId);
					CheckCategoryButtonEnable(categoryButtons[categoryIndexSelector.CurrentIndex]);
					RefreshCapsuleInfo(false);
					if (Dpr.BallDeco.BallDecoWork.GetSealCount(cursor.SelectedSealId) == 0)
					{
						cursor.Unselect();
						UpdateSwitchPalletIconActive();
					}
				}
				else
				{
					currentCapsuleInfo.SetAffixSeal(pickedAffixSealId, (ushort)cursor.SelectedSealId, selectedCapsule2DGridCell.GetSealPosition());
					if (selectedCapsule2DGridCell == pickedCapsule2DGridCell)
					{
						if (selectedCapsule2DGridCell.AffixSealId == pickedAffixSealId)
						{
							pickedCapsule2DGridCell.ShowAffixSeal();
						}
						else
						{
							selectedCapsule2DGridCell.SetAffixSeal(pickedAffixSealId, cursor.SelectedSealId);
						}
					}
					else
					{
						selectedCapsule2DGridCell.SetAffixSeal(pickedAffixSealId, cursor.SelectedSealId);
						if (!pickedCapsule2DGridCell.IsSetSeal)
						{
							pickedCapsule2DGridCell.ClearAffixSeal();
						}
					}
					ClearPickedSeal();
					cursor.Unselect();
					UpdateSwitchPalletIconActive();
				}
				CheckCursorRaycast(true, true, false);
				return DecideActionResult.AffixedSeal;
			}
			if (isBindCategoryTab)
			{
				if (!categoryButtons[categoryIndexSelector.CurrentIndex].IsNoneCategory && currentCapsuleInfo.IsAffixSealMaxCount)
				{
					OnSelectSealWhenAffixSealMaxCount?.Invoke();
					return DecideActionResult.Default;
				}
				return DecideActionResult.None;
			}
			if (isShowPullDown)
			{
				if (currentHitTransform == null)
				{
					return DecideActionResult.None;
				}
				SealButton sealButton = currentHitTransform.GetComponent<SealButton>();
				if (sealButton == null || !sealButton.IsEnable)
				{
					return DecideActionResult.None;
				}
				cursor.Selected(sealButton.SealId);
				pickedLatestPalletIndex = selectPalletIndex;
				pickedLatestCategoryIndex = categoryIndexSelector.CurrentIndex;
				HidePullDown();
				CheckCursorRaycast(true, true, true);
				if (!currentCapsuleInfo.Is3DEditMode)
				{
					Capsule2DViewController.ResetCurrentGridCell();
					selectedCapsule2DGridCell = Capsule2DViewController.GetCurrentGridCell();
					cursor.SetPosition(selectedCapsule2DGridCell.GetPosition());
				}
				return DecideActionResult.Default;
			}
			if (currentCapsuleInfo.Is3DEditMode)
			{
				if (currentHitTransform == null || selectedSeal3DObject == null)
				{
					return DecideActionResult.None;
				}
				SetPickedSeal(selectedSeal3DObject);
				cursor.Selected(pickedSeal3DObject.SealId);
				UpdateSwitchPalletIconActive();
				pickedSeal3DObject.SetActive(false);
			}
			else
			{
				if (selectedCapsule2DGridCell == null || !selectedCapsule2DGridCell.IsSetSeal)
				{
					return DecideActionResult.None;
				}
				SetPickedSeal(selectedCapsule2DGridCell);
				cursor.Selected(selectedCapsule2DGridCell.SealId);
				UpdateSwitchPalletIconActive();
				selectedCapsule2DGridCell.HideAffixSeal();
			}
			CheckCursorRaycast(true, true, true);
			return DecideActionResult.PickedSeal;
		}
		private void SwitchMode() {
			if (currentCapsuleInfo.IsAffixedSeal)
			{
				msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Seal, new string[] { "DLP_stickers_035", "DLP_stickers_036" }, null, true, false, () =>
				{
					Dpr.MsgWindow.MsgWindowManager.OpenYesNoMenu(selectIndex =>
					{
						msgWindowController.CloseMsgWindow();
						if (selectIndex != 0)
						{
							return;
						}
						currentCapsuleInfo.RemoveAllAffixSeals();
						currentCapsuleInfo.SwitchEditMode();
						RefreshCapsuleInfo(true);
						UpdatePallet();
						UpdateKeyGuide(false);
						CheckCursorRaycast(true, true, false);
					});
				}, null);
			}
			else
			{
				currentCapsuleInfo.SwitchEditMode();
				RefreshCapsuleInfo(true);
				UpdateKeyGuide(false);
				CheckCursorRaycast(true, true, false);
			}
		}
		private void ShowPullDown(global::UnityEngine.Vector3 pos) {
			pullDownRectTransform.position = pos;
			if (!isShowPullDown)
			{
				pullDownRectTransform.gameObject.SetActive(true);
			}
			capsuleViewController.SetDisablePreviewGuide(true);
			isShowPullDown = true;
			isBindCategoryTab = false;
			UpdateSwitchPalletIconActive();
		}
		private void HidePullDown() {
			pullDownRectTransform.gameObject.SetActive(false);
			capsuleViewController.SetDisablePreviewGuide(false);
			cursor.SetInfoText(null, false);
			isShowPullDown = false;
			UpdateSwitchPalletIconActive();
		}
		private void UpdatePullDownCursor() {
			if (pullDownIndexSelector.CurrentIndex < 0)
			{
				return;
			}
			SealButton sealButton = pullDownSealButtons[pullDownIndexSelector.CurrentIndex];
			currentHitTransform = sealButton.transform;
			cursor.SetPosition(currentHitTransform.position);
			Rect rect = GetRect((RectTransform)transform);
			Rect infoTextRect = GetRect(cursor.GetInfoTextRightRectTransform());
			cursor.SetInfoText(sealButton.Info, !rect.Contains(new Vector2(infoTextRect.x + infoTextRect.width, infoTextRect.y)));
			isBindCategoryTab = false;
			UpdateKeyGuide(false);
		}
		private void UpdateCursorPositionToCurrentCategory() {
			currentHitTransform = categoryButtons[categoryIndexSelector.CurrentIndex].transform;
			cursor.SetPosition(currentHitTransform.position);
			cursor.SetInfoText(null, false);
			isBindCategoryTab = true;
			UpdateKeyGuide(false);
		}
		private bool MoveCurrentCategoryButtonNearestGrid() {
			if (currentCapsuleInfo.Is3DEditMode)
			{
				HidePullDown();
			}
			else
			{
				Capsule2DGridCell gridCell = Capsule2DViewController.GetNearGridCell(categoryButtons[categoryIndexSelector.CurrentIndex].GetPosition());
				if (gridCell == null)
				{
					// shipped: returns without clearing isBindCategoryTab (@01e72fcc)
					return false;
				}
				selectedCapsule2DGridCell = gridCell;
				Capsule2DViewController.SetCurrentGridCell(gridCell);
				cursor.SetPosition(gridCell.GetPosition());
			}
			isBindCategoryTab = false;
			return true;
		}
		private void CheckCursorRaycast(bool isForce = false, bool isCheckMovable = true, bool isSelectSe = true) {
			if (isCheckMovable)
			{
				Rect movableRect = GetRect(cursorMovableRectTransform);
				Rect cursorRect = GetRect(cursor.GetRectTransform());
				if (!movableRect.Contains(cursorRect.min) || !movableRect.Contains(cursorRect.max))
				{
					cursor.SetPosition(beforeCursorPosition);
					return;
				}
				beforeCursorPosition = cursor.GetPosition();
			}
			Vector3 cursorPosition = cursor.GetPosition();
			bool isNoHit = true;
			if (currentCapsuleInfo.Is3DEditMode)
			{
				RaycastHit hit = Capsule3DViewController.Raycast(cursorPosition, out selectedSeal3DObject);
				if (hit.transform != null && !Capsule3DViewController.IsHitCapsule)
				{
					isNoHit = false;
					if (isForce || currentHitTransform != hit.transform)
					{
						currentHitTransform = hit.transform;
						isHoverCategoryTab = false;
						isHoverSetSealGridCell = false;
						if (selectedSeal3DObject != null && selectedSeal3DObject.IsSetSeal)
						{
							if (isSelectSe)
							{
								Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
							}
							isHoverSetSealGridCell = true;
							UpdateKeyGuide(false);
							return;
						}
					}
				}
			}
			int hitCount = Physics2D.RaycastNonAlloc(cursorPosition, Vector2.zero, raycastHit2Ds);
			if (hitCount > 0)
			{
				RaycastHit2D hit2D = raycastHit2Ds[0];
				float distance = hit2D.distance;
				for (int i = 1; i < hitCount; i++)
				{
					if (distance > raycastHit2Ds[i].distance)
					{
						hit2D = raycastHit2Ds[i];
						distance = hit2D.distance;
					}
				}
				if (!isForce && currentHitTransform == hit2D.transform)
				{
					return;
				}
				currentHitTransform = hit2D.transform;
				cursor.SetPosition(currentHitTransform.position);
				if (isSelectSe)
				{
					Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SELECT, null);
				}
				isHoverCategoryTab = false;
				isHoverSetSealGridCell = false;
				SealCategoryButton categoryButton = currentHitTransform.GetComponent<SealCategoryButton>();
				if (categoryButton == null)
				{
					return;
				}
				isHoverCategoryTab = true;
				isBindCategoryTab = true;
				if (pickedCapsule2DGridCell != null)
				{
					if (pickedCapsule2DGridCell.AffixSealId == pickedAffixSealId)
					{
						pickedCapsule2DGridCell.ShowAffixSeal();
					}
					ClearPickedSeal();
				}
				else if (pickedSeal3DObject != null)
				{
					pickedSeal3DObject.SetActive(true);
					ClearPickedSeal();
				}
				cursor.Unselect();
				for (int i = 0; i < categoryButtons.Length; i++)
				{
					if (categoryButton.CategoryId == categoryButtons[i].CategoryId)
					{
						categoryIndexSelector.SetCurrentIndex(i);
						break;
					}
				}
				RefreshShowPullDown(true);
			}
			else
			{
				if (!isNoHit)
				{
					return;
				}
				currentHitTransform = null;
				isBindCategoryTab = false;
				isHoverCategoryTab = false;
				isHoverSetSealGridCell = false;
			}
			UpdateKeyGuide(false);
		}
		private global::System.Collections.IEnumerator DelayCheckCursorRaycast(bool isForce = false, bool isCheckMovable = true, bool isSelectSe = true) {
			yield return null;
			CheckCursorRaycast(isForce, isCheckMovable, isSelectSe);
		}
		private void RefreshShowPullDown(bool isMoveCursorCurrentCategory = true) {
			int pullDownIndex = -1;
			if (isShowPullDown)
			{
				pullDownIndex = pullDownIndexSelector.CurrentIndex;
				HidePullDown();
			}
			if (categoryIndexSelector.CurrentIndex == -1)
			{
				return;
			}
			SealCategoryButton categoryButton = categoryButtons[categoryIndexSelector.CurrentIndex];
			SetupPullDown(categoryButton);
			if (pullDownIndexSelector.MaxCount >= 0)
			{
				ShowPullDown(categoryButton.GetPosition());
			}
			if (pullDownIndex < 0 || isMoveCursorCurrentCategory)
			{
				UpdateCursorPositionToCurrentCategory();
			}
			else
			{
				pullDownIndexSelector.SetCurrentIndex(pullDownIndex);
				UpdatePullDownCursor();
			}
		}
		private void RefreshCapsuleInfo(bool isReset = false) {
			currentCapsuleInfo.RefreshData();
			capsuleViewController.Setup(currentCapsuleInfo, isReset);
			UpdateSealCountView();
			if (isReset)
			{
				Capsule2DViewController.ResetCurrentGridCell();
				Capsule3DViewController.ShowEditMode();
				if (!currentCapsuleInfo.Is3DEditMode)
				{
					cursor.SetPosition(Capsule2DViewController.GetCurrentGridCell().GetPosition());
				}
				isChangeRotate = false;
			}
		}
		private void UpdatePallet() {
			int i = 0;
			int offset = selectPalletIndex * categoryButtons.Length;
			for (; i < categoryButtons.Length; i++)
			{
				if (offset + i >= palletCategoryIds.Length)
				{
					break;
				}
				categoryButtons[i].Set(palletCategoryIds[offset + i]);
				CheckCategoryButtonEnable(categoryButtons[i]);
			}
			for (; i < categoryButtons.Length; i++)
			{
				categoryButtons[i].SetNone();
				categoryButtons[i].SetEnable(false);
			}
			UpdateSwitchPalletIconActive();
		}
		private void SwitchPallet() {
			bool beforeShowPullDown = isShowPullDown;
			if (isShowPullDown)
			{
				HidePullDown();
			}
			selectPalletIndex = selectPalletIndex + 1 > maxPalletIndex ? 0 : selectPalletIndex + 1;
			if (dummyPalletObject == null)
			{
				dummyPalletObject = UnityEngine.Object.Instantiate(sealPalletRectTransform.gameObject, sealPalletRectTransform.parent);
			}
			else
			{
				SealCategoryButton[] dummyButtons = dummyPalletObject.GetComponentsInChildren<SealCategoryButton>();
				for (int i = 0; i < dummyButtons.Length; i++)
				{
					dummyButtons[i].Set(categoryButtons[i].CategoryId);
				}
				dummyPalletObject.transform.SetAsLastSibling();
				dummyPalletObject.SetActive(true);
			}
			UpdatePallet();
			Vector3 startPos = sealPalletRectTransform.localPosition + new Vector3(10f, -10f);
			Vector3 movePos1 = startPos + new Vector3(10f, 10f);
			Vector3 movePos2 = movePos1 + new Vector3(-10f, 15f);
			Vector3 movePos3 = movePos2 + new Vector3(-15f, -10f);
			Vector3 endPos = sealPalletRectTransform.localPosition;
			isAnimation = true;
			DG.Tweening.Sequence sequence = DOTween.Sequence();
			sequence.OnStart(() => sealPalletRectTransform.localPosition = startPos);
			sequence.Append(sealPalletRectTransform.DOLocalMove(movePos1, 0.2f, false).SetEase(Ease.Linear));
			sequence.Append(sealPalletRectTransform.DOLocalMove(movePos2, 0.2f, false).SetEase(Ease.Linear).OnComplete(() => dummyPalletObject.transform.SetAsFirstSibling()));
			sequence.Append(sealPalletRectTransform.DOLocalMove(movePos3, 0.2f, false).SetEase(Ease.Linear));
			sequence.Append(sealPalletRectTransform.DOLocalMove(endPos, 0.2f, false).SetEase(Ease.Linear));
			sequence.OnComplete(() =>
			{
				dummyPalletObject.SetActive(false);
				isAnimation = false;
				if (beforeShowPullDown)
				{
					RefreshShowPullDown(true);
				}
			});
			sequence.Play();
		}
		private void CheckCategoryButtonEnable(global::Dpr.UI.SealCategoryButton button) {
			bool isEnable = false;
			if (categoryzedSealInfoDic.TryGetValue(button.CategoryId, out SealInfo[] sealInfos))
			{
				for (int i = 0; i < sealInfos.Length; i++)
				{
					if (sealInfos[i].GetCount() > 0)
					{
						isEnable = true;
						break;
					}
				}
			}
			button.SetEnable(isEnable);
		}
		private void SetupPullDown(global::Dpr.UI.SealCategoryButton categoryButton) {
			pullDownCategoryButton.Set(categoryButton);
			int maxIndex = -1;
			int i = 0;
			if (categoryzedSealInfoDic.TryGetValue(categoryButton.CategoryId, out SealInfo[] sealInfos))
			{
				for (; i < sealInfos.Length && i < pullDownSealButtons.Length; i++)
				{
					pullDownSealButtons[i].Set(sealInfos[i].SealId);
					pullDownSealButtons[i].SetActive(true);
				}
				maxIndex = sealInfos.Length - 1;
			}
			for (; i < pullDownSealButtons.Length; i++)
			{
				pullDownSealButtons[i].SetActive(false);
			}
			pullDownIndexSelector.Setup(0, maxIndex);
		}
		private void UpdateSealCountView() {
			sealEditSealCountView.Set(currentCapsuleInfo.Data.AffixSealCount);
		}
		private void UpdateSwitchPalletIconActive() {
			if (canSwitchPallet)
			{
				isAllowSwicthPallet = !cursor.IsSelected;
				switchPalletIconObject.SetActive(isAllowSwicthPallet);
			}
		}
