			pickedCapsule2DGridCell = null;
			pickedSeal3DObject = null;
			pickedAffixSealId = -1;
		}
		private void OnReverseCapsule2D() {
			Capsule2DViewController.Setup(currentCapsuleInfo, false);
			CheckCursorRaycast(true, true, true);
			isAnimation = false;
			if (pickedCapsule2DGridCell != null && pickedCapsule2DGridCell.AffixSealId == pickedAffixSealId)
			{
				pickedCapsule2DGridCell.HideAffixSeal();
			}
		}
		private void CheckCursorInMovableRect() {
			RectTransform cursorRectTransform = cursor.GetRectTransform();
			Rect movableRect = GetRect(cursorMovableRectTransform);
			Rect cursorRect = GetRect(cursorRectTransform);
			Vector2 anchoredPosition = cursorRectTransform.anchoredPosition;
			if (cursorRect.xMin < movableRect.xMin)
			{
				anchoredPosition.x += movableRect.xMin - cursorRect.xMin;
			}
			else if (cursorRect.xMax > movableRect.xMax)
			{
				anchoredPosition.x -= cursorRect.xMax - movableRect.xMax;
			}
			if (cursorRect.yMin < movableRect.yMin)
			{
				anchoredPosition.y += movableRect.yMin - cursorRect.yMin;
			}
			else if (cursorRect.yMax > movableRect.yMax)
			{
				// shipped: the yMax overflow is subtracted from x, not y (fsub s8 @01e72ea0)
				anchoredPosition.x -= cursorRect.yMax - movableRect.yMax;
			}
			cursorRectTransform.anchoredPosition = anchoredPosition;
			beforeCursorPosition = cursor.GetPosition();
		}
		private global::UnityEngine.Rect GetRect(global::UnityEngine.RectTransform rectTransform) {
			rectTransform.GetWorldCorners(rectCorners);
			Vector3 min = rectCorners[0];
			Vector3 max = rectCorners[0];
			for (int i = 1; i < rectCorners.Length; i++)
			{
				min = Vector3.Min(min, rectCorners[i]);
				max = Vector3.Max(max, rectCorners[i]);
			}
			return Rect.MinMaxRect(min.x, min.y, max.x, max.y);
		}
